-- MySQL 8: encrypt a table's tablespace (keyring component must be loaded)
CREATE TABLE customers (
  id BIGINT PRIMARY KEY,
  email VARCHAR(255) NOT NULL
) ENCRYPTION='Y';

-- MySQL 8: find tables that are NOT encrypted
SELECT table_schema, table_name, create_options
FROM information_schema.tables
WHERE table_schema NOT IN ('mysql','sys','information_schema','performance_schema')
  AND (create_options IS NULL OR create_options NOT LIKE '%ENCRYPTION="Y"%');

-- PostgreSQL: confirm stored values are ciphertext, not plaintext
SELECT id, left(encode(national_id_enc, 'hex'), 24) AS stored_prefix
FROM customers LIMIT 2;

